static void Initialise(Thing* trophy, Thing* creature, bool hasSubDef, bool knowsEffect, Thing** emitterOut)
{
    if (trophy && !trophy->dead)
        trophy->shower = creature;
    long effectType = 0;
    if (creature && hasSubDef && knowsEffect) {
        effectType = 5;
