        if (marker && !(marker->ThingFlags & 1))
            target = marker->GetPosition();
        else {
            const C3DVector& pos = GetCreature()->GetPosition();
            target = C3DVector(pos.X - 2.0f, pos.Y - 2.0f, pos.Z);
            target.Z = GetWorldMap()->GetHeightZBelowPos(target);
